import { comment, commonEvent, showText } from "rpgmaker-event-dsl";

export const commonEventEvidenceCommonEvent001 = commonEvent({
  id: 1,
  name: "Evidence Common Event",
  trigger: "none",
  commands: [
    showText({ lines: ["Synthetic CR\rkept",""], background: 1, positionType: 0 }),
    comment(["Self-authored fixture",""]),
  ],
});
import { actorRef, imageAsset, itemRef, mapEvent, page, switchRef, variableRef } from "rpgmaker-event-dsl";

export const mapEventCompleteBlank001 = mapEvent({
  mapId: 1,
  id: 1,
  name: "Full saved replacement",
  note: "  <tag: x>\r\n\n<tag:y>\rtrailing\n",
  x: 0,
  y: 0,
  pages: [
    page({
      conditions: {
        switch1: { enabled: false, ref: switchRef({ id: 0 }) },
        switch2: { enabled: false, ref: switchRef({ id: 9999 }) },
        variable: { enabled: false, ref: variableRef({ id: 9999 }), atLeast: -99999999 },
        item: { enabled: false, ref: itemRef({ id: 9999 }) },
        actor: { enabled: false, ref: actorRef({ id: 0 }) },
        selfSwitch: { enabled: false, value: "D" },
      },
      image: { character: imageAsset({ folder: "characters", name: "!$Big" }), characterIndex: 7, tileId: 1023, direction: "up", pattern: 2 },
      movement: { speed: 6, frequency: 5, route: { commands: [{ kind: "routeWait", frames: 2, savedShape: { indent: "null" } }], repeat: false, skippable: true, wait: true, terminator: { parameters: "absent" } } },
      priority: "above",
      options: { walkAnimation: false, stepAnimation: true, directionFix: true, through: true },
      trigger: "parallel",
      commands: [

      ],
    }),
    page({
      conditions: {
        switch1: { enabled: true, ref: switchRef({ id: 1 }) },
        switch2: { enabled: true, ref: switchRef({ id: 2 }) },
        variable: { enabled: true, ref: variableRef({ id: 1 }), atLeast: 99999999 },
        item: { enabled: true, ref: itemRef({ id: 1 }) },
        actor: { enabled: true, ref: actorRef({ id: 1 }) },
        selfSwitch: { enabled: true, value: "B" },
      },
      image: { characterIndex: 6, direction: "left", pattern: 1 },
      movement: { type: "custom", speed: 1, frequency: 1 },
      priority: "same",
      trigger: "autorun",
      commands: [

      ],
    }),
    page({
      movement: { type: "approach" },
      trigger: "eventTouch",
      commands: [

      ],
    }),
    page({
      movement: { type: "random" },
      trigger: "playerTouch",
      commands: [

      ],
    }),
    page({
      commands: [

      ],
    })
  ],
});
import { switchDefinition, variableDefinition } from "rpgmaker-event-dsl";

export const switchOne001 = switchDefinition({
  id: 1,
  name: "One",
});

export const switchTwo002 = switchDefinition({
  id: 2,
  name: "Two",
});

export const variableValue001 = variableDefinition({
  id: 1,
  name: "Value",
});

