import { comment, commonEvent, showText } from "rpgmaker-event-dsl";

export const commonEventEvidenceCommonEvent001 = commonEvent({
  id: 1,
  name: "Evidence Common Event",
  trigger: "none",
  commands: [
    showText({ lines: ["Synthetic CR\rkept",""], background: 1, positionType: 0 }),
    comment(["Self-authored fixture",""]),
  ],
});
export {};
import { switchDefinition, variableDefinition } from "rpgmaker-event-dsl";

export const switchSavedSwitch001 = switchDefinition({
  id: 1,
  name: "Saved switch",
});
